import pandas as pd
import numpy as np

def run(inputs: dict) -> dict:
    df = inputs["payments"].copy()

    # Ensure the expected columns exist
    for col in ["payment_id", "amount", "currency", "country"]:
        if col not in df.columns:
            df[col] = pd.NA

    valid_currencies = {"USD", "EUR", "GBP"}

    reason_codes = []

    for idx, row in df.iterrows():
        amount = row["amount"]
        currency = row["currency"]
        country = row["country"]

        reason = None

        # R1: amount IS NULL
        if pd.isna(amount):
            reason = "AMT_NULL"
        else:
            # R2: amount <= 0
            if amount <= 0:
                reason = "AMT_NONPOS"
            else:
                # R3: currency NOT IN ('USD','EUR','GBP')
                # SQL NULL semantics: if currency is NULL, "NOT IN" is UNKNOWN,
                # so this rule does not fire; fall through to next rule.
                if pd.isna(currency):
                    pass
                elif currency not in valid_currencies:
                    reason = "CCY_INVALID"

                if reason is None:
                    # R4: country IS NULL
                    if pd.isna(country):
                        reason = "CTRY_NULL"

        reason_codes.append(reason)

    df = df.copy()
    df["__reason_code__"] = reason_codes

    reject_mask = df["__reason_code__"].notna()

    clean_df = df.loc[~reject_mask, ["payment_id", "amount", "currency", "country"]].copy()
    clean_df["amount"] = clean_df["amount"].astype(float).round(2)

    rejects_df = df.loc[reject_mask, ["payment_id", "amount", "currency", "country"]].copy()
    rejects_df["reason_code"] = df.loc[reject_mask, "__reason_code__"].values

    clean_df = clean_df.reset_index(drop=True)
    rejects_df = rejects_df.reset_index(drop=True)

    return {
        "payments_clean": clean_df,
        "payments_rejects": rejects_df,
    }
